import{d as p,C as t,o as g,c as d,a3 as s,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第三十三章","description":"《正易心法》第三十三章——凡物之数，有进有退：盛衰之数相半，进以此数退以此数；一岁十二月、昼夜十二时、人寿百岁、干支相邻，皆见进退，细推物理无不如然。","frontmatter":{"title":"正易心法·第三十三章","description":"《正易心法》第三十三章——凡物之数，有进有退：盛衰之数相半，进以此数退以此数；一岁十二月、昼夜十二时、人寿百岁、干支相邻，皆见进退，细推物理无不如然。","category":"guide","aliases":["正易心法第三十三章","进以此数退以此数","进退相半"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-33.md","filePath":"yijing/zheng-yi-xin-fa/chapter-33.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-33.md"},x=p({...c,setup(u){const i=[{id:"z33-01",label:"一、有进有退",showLabel:!0,sentences:[["凡物之数，有进有退。进以此数，退以此数。"]],note:["万物的数理有进有退：进用这个数，退也用这个数。（**「这个数」是同一个数**——不是两套规律，是同一套规律的两个方向。**就像上山与下山：走的是同一条路，只是方向相反。**）"]},{id:"z33-02",label:"二、盛衰之数相半",showLabel:!0,sentences:[["大抵",{text:"物理",glossary:"wuli"},"，其",{text:"盛衰之数相半",glossary:"shengshuaiXiangban"},"。方其盛也，既以此数。及其衰也，亦以此数。"]],note:["大体上，事物的道理，盛的数量与衰的数量各占一半。正当它旺盛的时候，用的就是这个数；等到它衰退的时候，也用的是这个数。（**这不是经验归纳，而是循环本身的逻辑要求**：如果盛＞衰，事物会无限增长；如果盛＜衰，会最终归零——**只有盛＝衰，循环才能成立。** 所以「相半」是一条守恒律。）"]},{id:"z33-03",label:"三、一岁与昼夜",showLabel:!0,sentences:[["若一岁十二月，春夏为进数，秋冬为退数。昼夜十二时，自子为进数，自午为退数。"]],note:["比如一年十二个月：春夏是进数，秋冬是退数。昼夜十二时辰：从子时开始是进数，从午时开始是退数。（**两处都是「各占一半」**：一年前半年进、后半年退；一日前半日子→午进，后半日午→子退。**而子与午正是阴阳的两个极点**——子时一阳生，午时一阴生。）"]},{id:"z33-04",label:"四、人寿与干支",showLabel:!0,sentences:[["人寿百岁，前五十为进数，后五十为退数。以至甲为进数，乙为退数。子为进数，丑为退数。"]],note:["人的寿命百岁：前五十年是进数，后五十年是退数。乃至甲是进数、乙是退数；子是进数、丑是退数。（**用「进退相半」看人的一生**：前五十不是「好」，后五十不是「坏」——**进退是同一个数的两面。** 而天干地支的「甲进乙退、子进丑退」是最小单位的进退节律：**阴阳交替，一步一步。**）"]},{id:"z33-05",label:"五、细推物理",showLabel:!0,sentences:[["细推物理，无不如然。"]],note:["仔细推演万物之理，无不如此。（**这是《正易心法》中最强的一句普遍性宣称**——前面各章的「此象之自然」「自然吻合，无余欠矣」「无余蕴矣」都是针对具体命题的宣称，**而这一句是「万物之理，无一例外」。**）"]},{id:"z33-06",label:"六、世儒衍为一律",showLabel:!0,sentences:[["世儒论教，但",{text:"衍为一律",glossary:"yanyuYilv"},"，殊不明阴阳进退之理，惟真人独得其说。"]],note:["世间儒者论述教化，只是把一切展开成同一个标准，竟然不明白阴阳进退的道理——只有真人独自得到了这个说法。（**「衍为一律」的批评有三种可能的指向**：① 只用阳数（进数）推演，忽略阴数（退数）；② 用固定公式套用一切，不知同一个数在不同阶段意义不同；③ 把道德教化也一律化，**只讲进（努力、上进、成就），不讲退（收敛、谦退、知止）。** **三种合读，「一律」的本质是：只看到规律的一个方向。**）"]}],o=[{id:"wuli",term:"物理",pinyin:"wù lǐ",meaning:"事物的道理，万物运行的内在规律。非现代「物理学」。"},{id:"shengshuaiXiangban",term:"盛衰之数相半",pinyin:"shèng shuāi zhī shù xiāng bàn",meaning:"盛的数量与衰的数量各占一半。不是观察所得，而是循环本身的逻辑要求（守恒律）。"},{id:"yanyuYilv",term:"衍为一律",pinyin:"yǎn wéi yī lǜ",meaning:"推演成一个统一模式。衍是推演，一律是一个模式。麻衣批评：只知单向，不知进退。"}];return(b,n)=>{const r=t("DaoTextReading"),l=t("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=s(`<h1 id="正易心法·第三十三章" tabindex="-1">正易心法·第三十三章 <a class="header-anchor" href="#正易心法·第三十三章" aria-label="Permalink to &quot;正易心法·第三十三章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章的核心命题：<strong>万物之数，进退对称，盛衰相半。进用这个数，退也用这个数。</strong></p><p><strong>具体例证</strong>：</p><table tabindex="0"><thead><tr><th>例</th><th>进</th><th>退</th></tr></thead><tbody><tr><td>一年十二个月</td><td>春夏（6 个月）</td><td>秋冬（6 个月）</td></tr><tr><td>昼夜十二时</td><td>子→午（6 时）</td><td>午→子（6 时）</td></tr><tr><td>人寿百岁</td><td>前五十年</td><td>后五十年</td></tr><tr><td>天干</td><td>甲</td><td>乙</td></tr><tr><td>地支</td><td>子</td><td>丑</td></tr></tbody></table><p><strong>批判</strong>：世儒只知「一律」（单向推演），不知阴阳进退之理。</p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「盛衰之数相半」是逻辑必然，不是经验归纳</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果盛 &gt; 衰：事物总体在增长，最终无限增长，不可能</span></span>
<span class="line"><span>如果盛 &lt; 衰：事物总体在减少，最终归零消亡，循环不成立</span></span>
<span class="line"><span>只有盛 = 衰：事物保持循环，进多少、退多少</span></span>
<span class="line"><span>= 宇宙循环的守恒定律</span></span></code></pre></div><p><strong>三层的时间尺度</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一年（年月）：春夏进，秋冬退</span></span>
<span class="line"><span>一日（时辰）：子→午进，午→子退</span></span>
<span class="line"><span>一生（人寿）：前五十进，后五十退</span></span></code></pre></div><p><strong>麻衣的深意</strong>：<strong>人不应该只看「前五十」（进）而忽视「后五十」（退）；也不应该只恐惧「后五十」（退）而留恋「前五十」（进）——进退是同一个数，生死是同一件事的两面。</strong></p><p><strong>「衍为一律」批评的三种可能</strong>：</p><table tabindex="0"><thead><tr><th>可能</th><th>内容</th></tr></thead><tbody><tr><td>一</td><td>只用阳数（进数）推演，忽略阴数（退数）——只看盛，不看衰</td></tr><tr><td>二</td><td>用固定公式套用一切，不知同一个数在不同阶段意义不同</td></tr><tr><td>三</td><td>把道德教化也一律化——只讲进（努力、上进），不讲退（收敛、知止）</td></tr></tbody></table><p><strong>三种合读：「一律」的本质是——只看到了规律的一个方向。</strong></p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把三处例证看成同一个结构：<strong>一年、一日、一生</strong>；</li><li>再看「相半」为什么是逻辑必然（不是观察所得）；</li><li>最后读「衍为一律」——<strong>这是本章的批评落点。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>有进有退</strong>：同一套数的两个方向。</li><li><strong>盛衰相半</strong>：循环成立的逻辑要求。</li><li><strong>一岁与昼夜</strong>：春夏秋冬，子午相半。</li><li><strong>人寿与干支</strong>：前五十为进，甲进乙退。</li><li><strong>细推物理</strong>：无不如然。</li><li><strong>衍为一律</strong>：世儒只知单向。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,20)),e(r,{colophon:"有进有退 · 盛衰相半 · 一岁昼夜人寿 · 无不如然",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十三章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（「大抵物理」之「物理」指事物之理，非今日之学科），不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"进以此数退以此数",pinyin:["jìn","cǐ"],meaning:"进和退用的是同一个数——不是两套规律，是同一套规律的两个方向，如上山与下山同一条路。"},{term:"盛衰之数相半",pinyin:["shèng","shuāi"],meaning:"盛的数量与衰的数量各半。这是循环成立的逻辑要求，不是观察所得。"},{term:"一岁与昼夜",pinyin:["yī","suì"],meaning:"春夏为进、秋冬为退；子→午为进、午→子为退。子与午正是阴阳的两个极点。"},{term:"人寿百岁",pinyin:["rén","shòu"],meaning:"前五十为进、后五十为退——进退是同一个数，生死是同一件事的两面。"},{term:"衍为一律",pinyin:["yǎn","wéi"],meaning:"推演成一个统一模式。麻衣批评世儒只知单向，不明白阴阳进退之理。"}]}),n[3]||(n[3]=s(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章的核心命题：<strong>万物之数，进退对称，盛衰相半；进以此数，退以此数。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一年：春夏进（6 月）、秋冬退（6 月）</span></span>
<span class="line"><span>一日：子→午进（6 时）、午→子退（6 时）</span></span>
<span class="line"><span>一生：前五十进、后五十退</span></span>
<span class="line"><span>干支：甲进乙退、子进丑退</span></span></code></pre></div><p><strong>批判</strong>：世儒只知「一律」（单向推演），不知阴阳进退之理。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「盛衰之数相半」是逻辑必然</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>盛 &gt; 衰 → 无限增长，不可能</span></span>
<span class="line"><span>盛 &lt; 衰 → 归零消亡，循环不成立</span></span>
<span class="line"><span>盛 = 衰 → 保持循环 = 宇宙的守恒性</span></span></code></pre></div><p><strong>「衍为一律」批评的三种可能</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 只用阳数（进数）推演，忽略阴数（退数）</span></span>
<span class="line"><span>② 用固定公式套用一切，不知数在不同阶段意义不同</span></span>
<span class="line"><span>③ 把道德教化也一律化——只讲进，不讲退</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三种合读：「一律」的本质是只看到规律的一个方向</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>把三处例证看成同一结构：<strong>一年、一日、一生</strong>；</li><li>记住「相半」是逻辑必然：<strong>不是「恰好一半」，是「必须一半」</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>「细推物理，无不如然」是可反驳的经验命题，还是不可反驳的框架命题？</strong> 我的看法：<strong>它更像框架命题</strong>——因为凡是不符合进退对称的现象，都可以被排除在「物理」之外（如宇宙膨胀、物种灭绝）。<strong>麻衣的「无不如然」，是「在我的框架里无不如然」。</strong> 但这不等于它无价值：<strong>框架的价值不在「能否被证伪」，而在「能否生成洞见」。</strong> 「进退相半」这个框架，确实让我对「前五十年／后五十年」有了新的看法：<strong>不是「好日子完了」，是「同一件事的另一半」。</strong> <strong>一个框架能让人换个方向看，就已经在做功了</strong>——至于它是不是「宇宙的真理」，那是另一个问题，而且<strong>大概不是麻衣要回答的问题。</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>万物的数理有进有退：进用这个数，退也用这个数。</p><p>大体上，事物的道理，盛的数量与衰的数量各占一半。正当它旺盛的时候，用的就是这个数；等到它衰退的时候，也用的是这个数。</p><p>比如一年十二个月：春夏是进数，秋冬是退数。昼夜十二时辰：从子时开始是进数，从午时开始是退数。</p><p>人的寿命百岁：前五十年是进数，后五十年是退数。乃至甲是进数、乙是退数；子是进数、丑是退数。</p><p>仔细推演万物之理，无不如此。</p><p>世间儒者论述教化，只是把一切展开成同一个标准，竟然不明白阴阳进退的道理——只有真人独自得到了这个说法。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第三十三章把「进退」从卦理推到了万物——<strong>一年、一日、一生，都是同一件事的两半。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「进以此数，退以此数」</strong>——<strong>同一个数</strong>。不是两套规律，是<strong>同一条路的上山与下山</strong>。这句话很朴素，但它消掉了「盛」与「衰」的对立。</li><li><strong>「盛衰之数相半」</strong>——麻衣给的理由是逻辑的：<strong>如果不对称，循环就不成立。</strong> 所以「相半」不是观察来的，是<strong>循环本身要求</strong>的。<strong>这是一条守恒律。</strong></li><li><strong>「人寿百岁，前五十为进数，后五十为退数」</strong>——这句话我读了两遍。<strong>它把「老」从「衰败」改成了「退数」。</strong> 退不是失去，是<strong>同一件事的另一半</strong>。</li><li><strong>「自子为进数，自午为退数」</strong>——子午是两个极点。<strong>气到极点，方向就换</strong>——不是「坏了一半」，是「换向」。</li><li><strong>「衍为一律」</strong>——麻衣的批评很有意思：<strong>不是「你算错了」，是「你只朝一个方向算」。</strong> 只讲进不讲退，只讲努力不讲知止——<strong>这种「一律」，今天也到处都是。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>「细推物理，无不如然」是可反驳的经验命题，还是不可反驳的框架命题？</strong> 我的看法：<strong>更像框架命题。</strong> 因为不符合进退对称的现象（宇宙膨胀、物种灭绝）都可以被排除在「物理」之外。<strong>麻衣的「无不如然」，是「在我的框架里无不如然」。</strong> 但这不等于它无价值：<strong>框架的价值不在「能否被证伪」，而在「能否生成洞见」</strong>——「进退相半」确实让我重新看待「前五十年／后五十年」。<strong>一个框架能让人换个方向看，就已经在做功了。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-25">第二十五章 · 中爻造化</a> — 「祸福倚伏」（本章「进退相半」的另一面）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-31">第三十一章 · 气数已尽</a> — 一岁之数三百六十（本章的时间尺度）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-32">第三十二章 · 数成于三</a> — 进数退数（本章的具体展开）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-34">第三十四章 · 五数十数</a> — 形的数（与本章的「物的数」相承）</li></ul>`,25))])}}});export{y as __pageData,x as default};
